using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ButtonDescriptionData", menuName = "Data/UIDescriptionData/ButtonDescriptionData", order = 0)]
public class ButtonDescriptionData : ScriptableObject
{
	private const string pressSelectID = "PressSelect";

	[SerializeField]
	protected string buttonName;

	[Header("Alignment")]
	[SerializeField]
	private bool tooltipUpAlignment = true;

	[SerializeField]
	private bool tooltipCenterAlignment;

	[Header("Name")]
	[SerializeField]
	[HideIf("ignoreName_NEnding")]
	private bool ignoreNameLocalization;

	[SerializeField]
	[ShowIf("ignoreNameLocalization")]
	private string nameWithoutLocalization;

	[SerializeField]
	[HideIf("ignoreNameLocalization")]
	private bool ignoreName_NEnding;

	[SerializeField]
	private bool useDifferentIDForName;

	[SerializeField]
	[ShowIf("useDifferentIDForName")]
	private string differentIDForName;

	[SerializeField]
	private bool enableCustomButtonName;

	[SerializeField]
	[ShowIf("enableCustomButtonName")]
	private CustomButtonNameData customButtonNameData;

	[SerializeField]
	private bool ignoreNameLineBreakCheck;

	[Header("Description")]
	[SerializeField]
	[HideIf("ignoreDescription_DEnding")]
	private bool ignoreDescriptionLocalization;

	[SerializeField]
	[ShowIf("ignoreDescriptionLocalization")]
	private string descriptionWithoutLocalization;

	[SerializeField]
	[HideIf("ignoreDescriptionLocalization")]
	private bool ignoreDescription_DEnding;

	[SerializeField]
	private bool useDifferentIDForDescription;

	[SerializeField]
	[ShowIf("useDifferentIDForDescription")]
	private string differentIDForDescription;

	[SerializeField]
	private bool enableCustomButtonDescription;

	[SerializeField]
	[ShowIf("enableCustomButtonDescription")]
	private CustomButtonDescriptionData customButtonDescriptionData;

	[Header("Input")]
	[SerializeField]
	private bool buttonWithJoystickKeyboardPrompt;

	[SerializeField]
	[ShowIf("buttonWithJoystickKeyboardPrompt")]
	private string actionName;

	[SerializeField]
	private bool secondButtonWithJoystickKeyboardPrompt;

	[SerializeField]
	[ShowIf("secondButtonWithJoystickKeyboardPrompt")]
	private string secondActionName;

	[SerializeField]
	[ShowIf("buttonWithJoystickKeyboardPrompt")]
	private bool hideJoystickKeyboardPrompt;

	[Header("Joystick and Mouse")]
	[SerializeField]
	private bool enableCustomJoystickAndMountFormat;

	[Header("Effects and Tags")]
	[SerializeField]
	private Effect[] effects = new Effect[0];

	[SerializeField]
	private Tag[] tags = new Tag[0];

	[SerializeField]
	private bool showTagsBeforeEffectsForDescriptions;

	public string ButtonName => GetLocalizedName();

	public virtual string ButtonDescription => GetLocalizedDescription();

	public bool TooltipUpAlignment => tooltipUpAlignment;

	public bool TooltipCenterAlignment => tooltipCenterAlignment;

	public bool IgnoreNameLineBreakCheck => ignoreNameLineBreakCheck;

	public bool ButtonWithJoystickKeyboardPrompt => buttonWithJoystickKeyboardPrompt;

	public string ActionName => actionName;

	public bool SecondButtonWithJoystickKeyboardPrompt => secondButtonWithJoystickKeyboardPrompt;

	public string SecondActionName => secondActionName;

	public bool HideJoystickKeyboardPrompt => hideJoystickKeyboardPrompt;

	public Tag[] Tags => GetTags();

	public bool ShowTagsBeforeEffectsForDescriptions => showTagsBeforeEffectsForDescriptions;

	protected virtual string GetLocalizedName()
	{
		if (ignoreNameLocalization)
		{
			return nameWithoutLocalization;
		}
		if (enableCustomButtonName)
		{
			return customButtonNameData.GetLocalizedName(buttonName + (ignoreName_NEnding ? "" : "_N"));
		}
		if (useDifferentIDForName)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(differentIDForName);
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(buttonName + (ignoreName_NEnding ? "" : "_N"));
	}

	protected virtual string GetLocalizedDescription()
	{
		if (ignoreDescriptionLocalization)
		{
			return descriptionWithoutLocalization;
		}
		if (enableCustomButtonDescription)
		{
			if (useDifferentIDForDescription)
			{
				return customButtonDescriptionData.GetLocalizedDescription(differentIDForDescription);
			}
			return customButtonDescriptionData.GetLocalizedDescription(buttonName + (ignoreDescription_DEnding ? "" : "_D"));
		}
		string text = "";
		text = ((!useDifferentIDForDescription) ? ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(buttonName + (ignoreDescription_DEnding ? "" : "_D")) : ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString(differentIDForDescription));
		if (enableCustomJoystickAndMountFormat)
		{
			text = Smart.Format(text, GetLocalizedClickInputString());
		}
		return text;
	}

	public virtual string GetAfterTintingLocalizedDescription(string description)
	{
		return description;
	}

	protected string GetLocalizedClickInputString()
	{
		if (!ReferenceSingleton<InputManager>.Instance.IsJoystickBeingUsed)
		{
			return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedClick();
		}
		return ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedString("PressSelect");
	}

	public virtual void OnMouseOver()
	{
	}

	public virtual bool IsButtonClickable()
	{
		return true;
	}

	public virtual bool CanShowButtonPrompt()
	{
		return true;
	}

	public virtual Effect[] GetEffects()
	{
		return effects;
	}

	public virtual Tag[] GetTags()
	{
		return tags;
	}
}
